    "description": "미래 세계는 마왕에 의해 파괴되어 거의 사라졌고, 유일하게 남은 각성자 성진은 탐식 마왕과 결전을 벌여 함께 최후를 맞이한다. 눈을 뜨자 성진은 세계가 파괴되기 10년 전의 모습으로 돌아와 있었다. 그뿐만 아니라, 그는 탐식의 힘을 되가져왔는데, 이 능력은 죽은 상대의 직업과 능력을 완전히 흡수하여 자신의 것으로 만들 수 있게 해준다. 잠이 들면 그의 몸속에는 강력한 악마들이 봉인된 마탑이 자리 잡고 있다! 이번 생의 유일한 혈육인 여동생을 구하고, 마탑 꼭대기에 있는 스승을 찾기 위해 그는 탐식자 계획을 실행하기로 결심한다. 이 계획은 자신의 몸속 마탑에 봉인된 악마들을 끊임없이 흡수하여 계속 강해지고, 여섯 마왕들이 아직 전성기에 도달하지 않은 지금, 그들을 찾아내어 소멸시키는 것이다."
