    "description": "평생을 가족을 위해 희생하며 살아온 어머니, 이경숙. 그녀는 헌신의 상징이었지만, 아들 서민욱은 단 한 번도 \"고맙다\"고 말하지 못했다. 어머니가 돌아가시고 후회 속에 살던 민욱은 믿기 힘든 기적과 함께 가족의 비극이 시작된 그날 외삼촌 이동호로 회귀한다. 외삼촌 이동호. 가족의 꿈과 희망을 짓밟고 떠난 그는 집안의 전 재산을 삼키며 모든 것을 무너뜨렸다. 돌아온 과거 속에서 민욱은 이를 바로잡으려 결심하지만, 점차 깊어지는 의문과 마주한다. “세상에 뿌려진 이 비를 우리 가족만 피할 수 있다면, 그것만으로 정말 만족할 수 있을까?” 과거를 구원하려는 그의 선택은 어머니를 진정으로 행복하게 만들 수 있을까? 희생과 후회, 그리고 구원의 서사가 지금 시작된다! ⓒ맷집왕,박정욱(원작:댄킴)/학산문화사"
