    "description": "“나랑 바람 좀 피워줘야겠어.” 황녀와의 억지 약혼을 깨기 위해 완벽한 외도 사기극을 꾸미는 대부호 공작, 레오폴드 오테로 폰 베른. 전 연인들이 황녀와 바람피워 헤어진 덕에 외도상담가가 된 몰락 귀족, 비올레타 헤르난데즈. 그녀는 의뢰인들의 상담비로 겨우 생계를 유지해 간다. 하지만 어느 날 가문이 진 거액의 채무이행서를 받게 되고, 남동생의 학비마저 급히 마련해야 하는 상황에까지 닥치는데……. “학비쯤이야, 남동생의 앞날까지 책임져 주지.” “제 앞날은요? 바람녀 딱지 붙으면 결혼은 꿈도 못 꿔요.” 그저 밥 먹고 살 정도의 사랑 가득한 결혼을 꿈꿨건만. 정녕 그의 바람녀가 되는 게 답인 걸까. “들키지 않게 해줄게. 흔적만 남겨. 황녀가 완벽히 오해할 만한.” 그렇게 시작된 대국민 외도 사기극. 바람피우는 척만 한다던 남자는 자꾸만 선을 넘어온다. “이따위 증거들이 통할 거로 생각하나?” “돈 값하러 온 거라며.” “키스 자국이라도 남기는 성의를 보이든가.” 아무래도… 그에게 잘못 걸린 것 같다."
