    "description": "\"내 후회는 그때 '그 마법'을 선택하지 않은 것.... 다음번에는 반드시 쓰러트려주지!\" 갑작스레 세상에 등장한 사신, 비드락의 손에 멸망의 기로에 선 인류. 수많은 마법 공격을 무효화시키는 비드락 앞에서 인류 최강의 원거리 마법을 구사하는 대마도사, 세츠나의 마법 역시 통하지 않고 인류는 무력하게 패배하게 되는데.... 최후의 순간 눈을 감았던 세츠나가 돌아온 건 10년 전, 마도학원에서 선택 의식을 치르던 순간이었다. 학생들이 각자 자신의 적성에 맞춰 마도사로서의 진로를 선택하는 가운데, 세츠나는 아무도 선호하지 않는 최악의 비인기 분야 '근접 마법'을 선택한다. \"근접 마법이야말로 사신을 쓰러트릴 유일한 방법이야!\" 다른 마법에 비해 약점이 많다고 알려진 근접 마법이지만, 세츠나는 특기인 섬세한 마력 컨트롤을 이용해 근접 마법을 그 어떤 마법보다도 강력하게 재탄생시키며 모두의 상식을 뒤엎는데..!"
